const rawInput = $input.first().json;
const payload = rawInput.body || rawInput;
const data = payload.data || payload;

const prNumber = data.pr_number || 'PR-UNKNOWN';
const totalBudget = Number(data.total_budget || 0).toLocaleString('id-ID');
const totalItems = data.total_items || (data.items ? data.items.length : 0);
const promptText = data.prompt || '-';

const approveUrl = data.approve_url || `http://127.0.0.1:8000/api/approval/quick-action?pr_number=${prNumber}&action=APPROVE`;
const rejectUrl = data.reject_url || `http://127.0.0.1:8000/api/approval/quick-action?pr_number=${prNumber}&action=REJECT`;
const pdfUrl = data.pdf_download_url || `http://127.0.0.1:8000/api/documents/pr/${prNumber}/download`;

const itemsList = (data.items || []).map((it, idx) => {
  const price = Number(it.total_price || 0).toLocaleString('id-ID');
  return `${idx + 1}. <b>${it.name}</b> (${it.reorder_qty} ${it.unit}) &rarr; Rp ${price} (Vendor: ${it.vendor_name || it.vendor_id})`;
}).join('\n');

const itemsHtml = (data.items || []).map((it, idx) => {
  const price = Number(it.total_price || 0).toLocaleString('id-ID');
  return `<li><strong>${it.name}</strong>: ${it.reorder_qty} ${it.unit} &rarr; <b>Rp ${price}</b> (Vendor: ${it.vendor_name || it.vendor_id})</li>`;
}).join('');

const telegramHtml = `🚨 <b>PERMINTAAN PERSETUJUAN RESTOCK (AutoRestock-Agent)</b>\n\n` +
  `📄 <b>No. PR:</b> <code>${prNumber}</code>\n` +
  `💬 <b>Instruksi:</b> <i>"${promptText}"</i>\n` +
  `📦 <b>Jumlah Item:</b> ${totalItems} SKU\n` +
  `💰 <b>Total Anggaran:</b> Rp ${totalBudget}\n` +
  `🕒 <b>Waktu:</b> ${payload.timestamp || new Date().toISOString()}\n\n` +
  `📋 <b>Rincian Pengadaan:</b>\n${itemsList || '- Tidak ada item -'}\n\n` +
  `⚡ <b>AKSI PERSETUJUAN DUA ARAH:</b>\n` +
  `✅ <a href="${approveUrl}"><b>KLIK UNTUK SETUJUI (Stok Bertambah)</b></a>\n` +
  `❌ <a href="${rejectUrl}"><b>KLIK UNTUK TOLAK (Stok Tetap)</b></a>\n\n` +
  `🔗 <a href="${pdfUrl}">Unduh Dokumen PDF Resmi</a>\n` +
  `📌 <b>Status:</b> PENDING APPROVAL`;

const emailSubject = `[PENGADAAN GUDANG] Permintaan Persetujuan Restock - ${prNumber}`;
const emailHtml = `<div style="font-family: 'Segoe UI', Arial, sans-serif; max-width: 620px; padding: 24px; border: 1px solid #e2e8f0; border-radius: 12px; background: #ffffff; color: #1e293b;">` +
  `<div style="background: #1e293b; color: #ffffff; padding: 18px; border-radius: 8px; text-align: center; margin-bottom: 20px;">` +
  `<h2 style="margin: 0; font-size: 20px;">🚨 Permintaan Persetujuan Restock Otomatis</h2>` +
  `<p style="margin: 6px 0 0 0; color: #94a3b8; font-size: 13px;">AutoRestock-Agent Procurement System</p>` +
  `</div>` +
  `<p>Sistem AI Agent telah menyintesis pengadaan baru berdasarkan instruksi: <i>"${promptText}"</i>.</p>` +
  `<table style="width: 100%; border-collapse: collapse; margin: 15px 0;">` +
  `<tr><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;"><strong>No. PR</strong></td><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;"><code>${prNumber}</code></td></tr>` +
  `<tr><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;"><strong>Total Item</strong></td><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;">${totalItems} SKU</td></tr>` +
  `<tr><td style="padding: 8px; border-bottom: 1px solid #e2e8f0;"><strong>Total Anggaran</strong></td><td style="padding: 8px; border-bottom: 1px solid #e2e8f0; color: #dc2626; font-weight: bold;">Rp ${totalBudget}</td></tr>` +
  `<tr><td style="padding: 8px;"><strong>Status Saat Ini</strong></td><td style="padding: 8px;"><span style="background:#eff6ff; color:#1e40af; padding: 4px 10px; border-radius: 4px; font-weight: bold;">PENDING APPROVAL</span></td></tr>` +
  `</table>` +
  `<h3>📋 Rincian Barang yang Perlu Di-restock:</h3>` +
  `<ul style="line-height: 1.8;">${itemsHtml || '<li>Tidak ada item</li>'}</ul>` +
  `<div style="background: #eff6ff; border-left: 4px solid #3b82f6; padding: 12px; border-radius: 4px; font-size: 13px; color: #1e40af; margin: 20px 0;">` +
  `💡 <strong>Aksi Satu-Klik Langsung ke Database:</strong><br>` +
  `• Klik <strong>Setujui (APPROVE)</strong>: Stok barang di DuckDB akan otomatis ditambahkan.<br>` +
  `• Klik <strong>Tolak (REJECT)</strong>: Pengadaan dibatalkan dan stok fisik tetap.` +
  `</div>` +
  `<div style="text-align: center; margin: 25px 0;">` +
  `<a href="${approveUrl}" style="background: #16a34a; color: #ffffff; text-decoration: none; padding: 12px 24px; border-radius: 8px; font-weight: bold; display: inline-block; margin-right: 10px;">✅ SETUJUI (APPROVE)</a>` +
  `<a href="${rejectUrl}" style="background: #dc2626; color: #ffffff; text-decoration: none; padding: 12px 24px; border-radius: 8px; font-weight: bold; display: inline-block;">❌ TOLAK (REJECT)</a>` +
  `</div>` +
  `<div style="text-align: center; margin-top: 15px;"><a href="${pdfUrl}" style="color: #2563eb; font-size: 13px; font-weight: 600;">📄 Unduh Dokumen PDF Resmi (${prNumber}.pdf)</a></div>` +
  `</div>`;

return {
  json: {
    status: 'received',
    event: payload.event || 'custom_workflow_execution',
    pr_number: prNumber,
    total_budget_idr: totalBudget,
    total_items: totalItems,
    items: data.items || [],
    approve_url: approveUrl,
    reject_url: rejectUrl,
    pdf_download_url: pdfUrl,
    telegram_message: telegramHtml,
    email_subject: emailSubject,
    email_html: emailHtml,
    recipient_email: data.recipient_email || 'manager@company.com',
    received_at: new Date().toISOString()
  }
};
